class Provider {
    constructor() {
        this.api = "https://www.webtoons.com";
        this.mobileApi = "https://m.webtoons.com";
        this.lang = "en";
    }

    getSettings() {
        return {
            supportsMultiLanguage: false,
            supportsMultiScanlator: false,
        };
    }

    async search(opts) {
        var query = String((opts && opts.query) || "").trim();

        if (!query) {
            return await this.getPopular();
        }

        if (query.indexOf("webtoons.com") >= 0 && query.indexOf("title_no=") >= 0) {
            var titleNo = this.getTitleNo(query);
            var title = await this.getSeriesTitle(query);

            return [{
                id: this.normalizeUrl(query),
                title: title || ("WEBTOON " + titleNo),
                synonyms: [],
                year: 1,
                image: "",
            }];
        }

        var urls = [
            this.api + "/" + this.lang + "/search?keyword=" + encodeURIComponent(query),
            this.mobileApi + "/" + this.lang + "/search?keyword=" + encodeURIComponent(query),
        ];

        for (var i = 0; i < urls.length; i++) {
            try {
                var html = await this.fetchHTML(urls[i]);

                if (!html || html.length < 200) {
                    continue;
                }

                var results = this.parseSearchResults(html);

                if (results.length > 0) {
                    return results;
                }
            } catch (err) {
                console.error("webtoon: search failed: " + String(err));
            }
        }

        return [];
    }

    async findChapters(mangaId) {
        var listUrl = this.toListUrl(mangaId);

        if (!listUrl) {
            return [];
        }

        var titleNo = this.getTitleNo(listUrl);
        var allChapters = [];
        var seen = {};

        for (var page = 1; page <= 50; page++) {
            var pageUrl = this.withPage(listUrl, page);

            try {
                var html = await this.fetchHTML(pageUrl);

                if (!html || html.length < 200) {
                    break;
                }

                var chapters = this.parseChaptersFromHTML(html, titleNo);
                var added = 0;

                for (var i = 0; i < chapters.length; i++) {
                    var chapter = chapters[i];

                    if (!chapter.id || seen[chapter.id]) {
                        continue;
                    }

                    seen[chapter.id] = true;
                    allChapters.push(chapter);
                    added++;
                }

                if (added === 0) {
                    break;
                }

                if (!this.hasPagination(html) && page >= 2) {
                    break;
                }
            } catch (err) {
                console.error("webtoon: chapter page fetch failed: " + String(err));
                break;
            }
        }

        var deduped = this.dedupeChapters(allChapters);

        deduped.sort(function (a, b) {
            return Number(a.chapter || 0) - Number(b.chapter || 0);
        });

        for (var j = 0; j < deduped.length; j++) {
            deduped[j].index = j;

            if (!deduped[j].title) {
                deduped[j].title = "Episode " + (deduped[j].chapter || (j + 1));
            }

            if (!deduped[j].language) {
                deduped[j].language = "en";
            }
        }

        return deduped;
    }

    async findChapterPages(chapterId) {
        var url = this.normalizeUrl(chapterId);

        if (!url || url.indexOf("webtoons.com") < 0 || url.indexOf("episode_no=") < 0) {
            return [];
        }

        try {
            var html = await this.fetchHTML(url);

            if (!html || html.length < 200) {
                return [];
            }

            var images = this.parsePageImages(html);
            var pages = [];

            for (var i = 0; i < images.length; i++) {
                pages.push({
                    url: images[i],
                    index: i,
                    headers: {
                        Referer: url,
                        "User-Agent": "Mozilla/5.0",
                    },
                });
            }

            return pages;
        } catch (err) {
            console.error("webtoon: findChapterPages error: " + String(err));
            return [];
        }
    }

    async getPopular() {
        var urls = [
            this.api + "/" + this.lang + "/",
            this.api + "/" + this.lang + "/dailySchedule",
            this.mobileApi + "/" + this.lang + "/",
        ];

        for (var i = 0; i < urls.length; i++) {
            try {
                var html = await this.fetchHTML(urls[i]);
                var results = this.parseSearchResults(html);

                if (results.length > 0) {
                    return results;
                }
            } catch (err) {
                console.error("webtoon: popular failed: " + String(err));
            }
        }

        return [];
    }

    async getSeriesTitle(url) {
        try {
            var html = await this.fetchHTML(this.normalizeUrl(url));
            var title = this.cleanText(this.meta(html, "og:title"));

            return title
                .replace(/\s*\|\s*WEBTOON\s*$/i, "")
                .replace(/\s*-\s*WEBTOON\s*$/i, "")
                .trim();
        } catch (err) {
            return "";
        }
    }

    parseSearchResults(html) {
        var results = [];
        var seen = {};
        var self = this;

        try {
            var $ = LoadDoc(html);

            $("a[href*='/list?title_no=']").each(function (i, e) {
                var href = e.attr("href") || "";
                var fullUrl = self.normalizeUrl(href);
                var titleNo = self.getTitleNo(fullUrl);

                if (!titleNo || seen[String(titleNo)]) {
                    return;
                }

                seen[String(titleNo)] = true;

                var img =
                    e.find("img").attr("data-src") ||
                    e.find("img").attr("src") ||
                    e.find("img").attr("data-original") ||
                    "";

                var title =
                    e.attr("title") ||
                    e.find("img").attr("alt") ||
                    e.find(".subj").first().text() ||
                    e.find(".title").first().text() ||
                    e.find("h3").first().text() ||
                    e.find("h4").first().text() ||
                    e.find("p").first().text() ||
                    e.text() ||
                    "";

                title = self.cleanSearchTitle(title);

                if (!title) {
                    title = "WEBTOON " + titleNo;
                }

                results.push({
                    id: fullUrl,
                    title: title,
                    synonyms: [],
                    year: 1,
                    image: self.normalizeUrl(img),
                });
            });
        } catch (err) {
            console.error("webtoon: LoadDoc search parse failed: " + String(err));
        }

        var linkPattern = /<a[^>]+href=["']([^"']*\/list\?title_no=([0-9]+)[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
        var match;

        while ((match = linkPattern.exec(html)) !== null) {
            var href = this.decode(match[1] || "");
            var titleNo = Number(match[2] || 0);
            var inner = match[3] || "";

            if (!titleNo || seen[String(titleNo)]) {
                continue;
            }

            seen[String(titleNo)] = true;

            var title =
                this.cleanSearchTitle(this.firstMatch(inner, /title=["']([^"']+)["']/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /alt=["']([^"']+)["']/i)) ||
                this.cleanSearchTitle(inner) ||
                ("WEBTOON " + titleNo);

            var img =
                this.firstMatch(inner, /data-src=["']([^"']+)["']/i) ||
                this.firstMatch(inner, /src=["']([^"']+)["']/i) ||
                "";

            results.push({
                id: this.normalizeUrl(href),
                title: title,
                synonyms: [],
                year: 1,
                image: this.normalizeUrl(this.decode(img)),
            });
        }

        return results;
    }

    parseChaptersFromHTML(html, titleNo) {
        var chapters = [];
        var seen = {};
        var self = this;

        try {
            var $ = LoadDoc(html);

            $("a[href*='/viewer?']").each(function (i, e) {
                var href = e.attr("href") || "";
                var fullUrl = self.normalizeUrl(href);
                var foundTitleNo = self.getTitleNo(fullUrl);
                var episodeNo = self.getEpisodeNo(fullUrl);

                if (!episodeNo) {
                    return;
                }

                if (titleNo && foundTitleNo && foundTitleNo !== titleNo) {
                    return;
                }

                if (seen[fullUrl]) {
                    return;
                }

                seen[fullUrl] = true;

                var title =
                    e.attr("title") ||
                    e.find(".subj").first().text() ||
                    e.find(".episode").first().text() ||
                    e.find("span").first().text() ||
                    e.find("p").first().text() ||
                    e.text() ||
                    "";

                title = self.cleanChapterTitle(title, episodeNo);

                chapters.push({
                    id: fullUrl,
                    url: fullUrl,
                    title: title,
                    chapter: String(episodeNo),
                    index: 0,
                    language: "en",
                });
            });
        } catch (err) {
            console.error("webtoon: LoadDoc chapter parse failed: " + String(err));
        }

        var pattern = /<a[^>]+href=["']([^"']*\/viewer\?[^"']*episode_no=([0-9]+)[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
        var match;

        while ((match = pattern.exec(html)) !== null) {
            var href = this.decode(match[1] || "");
            var fullUrl = this.normalizeUrl(href);
            var foundTitleNo = this.getTitleNo(fullUrl);
            var episodeNo = Number(match[2] || 0);
            var inner = match[3] || "";

            if (!episodeNo) {
                continue;
            }

            if (titleNo && foundTitleNo && foundTitleNo !== titleNo) {
                continue;
            }

            if (seen[fullUrl]) {
                continue;
            }

            seen[fullUrl] = true;

            var title =
                this.cleanChapterTitle(this.firstMatch(inner, /title=["']([^"']+)["']/i), episodeNo) ||
                this.cleanChapterTitle(this.firstMatch(inner, /alt=["']([^"']+)["']/i), episodeNo) ||
                this.cleanChapterTitle(inner, episodeNo);

            chapters.push({
                id: fullUrl,
                url: fullUrl,
                title: title || ("Episode " + episodeNo),
                chapter: String(episodeNo),
                index: 0,
                language: "en",
            });
        }

        return chapters;
    }

    parsePageImages(html) {
        var images = [];
        var seen = {};
        var self = this;

        function add(raw) {
            var url = self.decode(String(raw || "").trim());

            if (!url) {
                return;
            }

            url = url
                .replace(/\\u0026/g, "&")
                .replace(/\\\//g, "/")
                .replace(/&amp;/g, "&");

            url = self.normalizeUrl(url);

            if (!self.isWebtoonPageImage(url)) {
                return;
            }

            if (seen[url]) {
                return;
            }

            seen[url] = true;
            images.push(url);
        }

        try {
            var $ = LoadDoc(html);

            var selectors = [
                "#_imageList img",
                ".viewer_img img",
                ".wt_viewer img",
                ".viewer_lst img",
                ".view_area img",
                "img[data-url]",
                "img[data-src]",
                "img[src]",
            ];

            for (var i = 0; i < selectors.length; i++) {
                $(selectors[i]).each(function (j, e) {
                    add(e.attr("data-url") || "");
                    add(e.attr("data-src") || "");
                    add(e.attr("data-original") || "");
                    add(e.attr("src") || "");
                });
            }
        } catch (err) {
            console.error("webtoon: LoadDoc image parse failed: " + String(err));
        }

        var patterns = [
            /https?:\\?\/\\?\/webtoon-phinf\.pstatic\.net\\?\/[^"'<>\\\s]+/gi,
            /https?:\/\/webtoon-phinf\.pstatic\.net\/[^"'<>\s]+/gi,
            /\/\/webtoon-phinf\.pstatic\.net\/[^"'<>\s]+/gi,
            /https?:\\?\/\\?\/[^"'<>\\\s]*webtoon[^"'<>\\\s]*pstatic[^"'<>\\\s]+/gi,
        ];

        for (var p = 0; p < patterns.length; p++) {
            var match;

            while ((match = patterns[p].exec(html)) !== null) {
                add(match[0]);
            }
        }

        return images;
    }

    isWebtoonPageImage(url) {
        var lower = String(url || "").toLowerCase();

        if (lower.indexOf("http") !== 0) {
            return false;
        }

        if (
            lower.indexOf("webtoon-phinf.pstatic.net") >= 0 ||
            lower.indexOf("webtoon-phinf.pstatic.com") >= 0
        ) {
            return true;
        }

        if (
            lower.indexOf("pstatic") >= 0 &&
            lower.indexOf("webtoon") >= 0 &&
            (
                lower.indexOf(".jpg") >= 0 ||
                lower.indexOf(".jpeg") >= 0 ||
                lower.indexOf(".png") >= 0 ||
                lower.indexOf(".webp") >= 0
            )
        ) {
            return true;
        }

        return false;
    }

    async fetchHTML(url) {
        var res = await fetch(url, {
            headers: {
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                "Accept-Language": "en-US,en;q=0.9",
                "User-Agent": "Mozilla/5.0",
                "Referer": this.api + "/",
            },
        });

        if (!res.ok) {
            throw new Error("HTTP " + res.status + " for " + url);
        }

        return await res.text();
    }

    toListUrl(input) {
        var value = String(input || "").trim();

        if (!value) {
            return "";
        }

        if (value.indexOf("webtoons.com") >= 0) {
            if (value.indexOf("/list?") >= 0) {
                return this.normalizeUrl(value);
            }

            if (value.indexOf("/viewer?") >= 0) {
                var titleNo = this.getTitleNo(value);
                if (titleNo) {
                    return this.api + "/" + this.lang + "/search?keyword=" + encodeURIComponent(String(titleNo));
                }
            }

            return this.normalizeUrl(value);
        }

        var id = this.getTitleNo(value);

        if (id) {
            return this.api + "/" + this.lang + "/search?keyword=" + encodeURIComponent(String(id));
        }

        return "";
    }

    withPage(url, page) {
        if (page <= 1) {
            return url;
        }

        if (url.indexOf("page=") >= 0) {
            return url.replace(/([?&])page=[0-9]+/i, "$1page=" + page);
        }

        return url + (url.indexOf("?") >= 0 ? "&" : "?") + "page=" + page;
    }

    normalizeUrl(url) {
        var value = this.decode(String(url || "").trim());

        if (!value) {
            return "";
        }

        value = value.replace(/&amp;/g, "&");

        if (value.indexOf("//") === 0) {
            return "https:" + value;
        }

        if (value.indexOf("/") === 0) {
            return this.api + value;
        }

        if (value.indexOf("http") === 0) {
            return value;
        }

        return this.api + "/" + value;
    }

    getTitleNo(input) {
        var text = String(input || "");
        var patterns = [
            /title_no=([0-9]+)/i,
            /titleNo=([0-9]+)/i,
            /^([0-9]+)$/,
        ];

        for (var i = 0; i < patterns.length; i++) {
            var match = text.match(patterns[i]);

            if (match && match[1]) {
                return Number(match[1]) || 0;
            }
        }

        return 0;
    }

    getEpisodeNo(input) {
        var text = String(input || "");
        var match = text.match(/episode_no=([0-9]+)/i);

        if (!match || !match[1]) {
            return 0;
        }

        return Number(match[1]) || 0;
    }

    hasPagination(html) {
        var lower = String(html || "").toLowerCase();

        return (
            lower.indexOf("page=") >= 0 ||
            lower.indexOf("paginate") >= 0 ||
            lower.indexOf("pagination") >= 0 ||
            lower.indexOf("next") >= 0
        );
    }

    meta(html, property) {
        var p1 = new RegExp("<meta[^>]+property=[\"']" + this.escapeRegExp(property) + "[\"'][^>]+content=[\"']([^\"']+)[\"']", "i");
        var p2 = new RegExp("<meta[^>]+content=[\"']([^\"']+)[\"'][^>]+property=[\"']" + this.escapeRegExp(property) + "[\"']", "i");
        var p3 = new RegExp("<meta[^>]+name=[\"']" + this.escapeRegExp(property) + "[\"'][^>]+content=[\"']([^\"']+)[\"']", "i");

        return this.decode(this.firstMatch(html, p1) || this.firstMatch(html, p2) || this.firstMatch(html, p3));
    }

    firstMatch(text, pattern) {
        var match = String(text || "").match(pattern);
        return match && match[1] ? match[1] : "";
    }

    cleanSearchTitle(input) {
        var text = this.cleanText(input);

        text = text
            .replace(/\s*\|\s*WEBTOON\s*$/i, "")
            .replace(/\s*-\s*WEBTOON\s*$/i, "")
            .replace(/^WEBTOON\s*/i, "")
            .replace(/\s+/g, " ")
            .trim();

        if (text.length > 160) {
            text = text.slice(0, 160).trim();
        }

        return text;
    }

    cleanChapterTitle(input, episodeNo) {
        var text = this.cleanText(input);

        text = text
            .replace(/\s+/g, " ")
            .replace(/^#?\s*0*/, "")
            .trim();

        if (!text) {
            return "Episode " + episodeNo;
        }

        if (text.length > 180) {
            text = text.slice(0, 180).trim();
        }

        var lower = text.toLowerCase();

        if (
            lower.indexOf("download webtoon now") >= 0 ||
            lower.indexOf("privacy") >= 0 ||
            lower.indexOf("terms") >= 0
        ) {
            return "Episode " + episodeNo;
        }

        return text;
    }

    cleanText(input) {
        return this.decode(
            String(input || "")
                .replace(/<script[\s\S]*?<\/script>/gi, " ")
                .replace(/<style[\s\S]*?<\/style>/gi, " ")
                .replace(/<[^>]+>/g, " ")
                .replace(/\s+/g, " ")
                .trim()
        );
    }

    decode(input) {
        return String(input || "")
            .replace(/&amp;/g, "&")
            .replace(/&quot;/g, "\"")
            .replace(/&#39;/g, "'")
            .replace(/&apos;/g, "'")
            .replace(/&lt;/g, "<")
            .replace(/&gt;/g, ">")
            .replace(/&#x2F;/g, "/")
            .replace(/&#47;/g, "/")
            .replace(/&nbsp;/g, " ");
    }

    escapeRegExp(input) {
        return String(input || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    }

    dedupeChapters(chapters) {
        var seen = {};
        var ret = [];

        for (var i = 0; i < chapters.length; i++) {
            var ch = chapters[i];
            var key = ch.id || ch.url || ch.chapter;

            if (!key || seen[key]) {
                continue;
            }

            seen[key] = true;
            ret.push(ch);
        }

        return ret;
    }
}
